/****************************************************************************
 * vendor/SpaceMiT/chips/k1-rcpu/k1r_userspace.c
 *
 * SpacemiT K1 RCPU (Nuclei N308) PROTECTED build 用户态/内存保护初始化
 *
 * 参考 c906_userspace.c（no-MMU + MPU PROTECTED RISC-V）：
 *   - k1r_userspace(): 清用户 .bss、拷贝用户 .data、配置 PMP（8 条 TOR）
 *   - up_allocate_kheap(): 内核堆（M-only）
 * 注意：N308 PMP 仅支持 TOR（无 NAPOT），且 pmpaddr 为 4 字节单位（boundary>>2，
 *      真机 Gate0 实测）。因此 configure_mpu 全部用 PMPCFG_A_TOR。
 *      布局：内核 [0x30000000, CONFIG_NUTTX_USERSPACE)，用户 [USERSPACE, USERSPACE_SIZE)。
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdint.h>
#include <assert.h>

#include <nuttx/userspace.h>
#include <nuttx/arch.h>

#include "riscv_internal.h"
#include "chip.h"

#ifdef CONFIG_BUILD_PROTECTED

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* 用户空间尺寸（默认 1MB；含用户 code/data/heap/stack） */
#ifndef CONFIG_NUTTX_USERSPACE_SIZE
#  define CONFIG_NUTTX_USERSPACE_SIZE        (0x00100000)
#endif

/* 内核运行区终点 = 用户空间基址（内核堆/内核栈/中断栈都在此之下） */
#define K1R_KERNEL_END        CONFIG_NUTTX_USERSPACE

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: configure_mpu
 *
 * Description:
 *   配置 PMP 把内核与用户态隔离。N308 只支持 TOR（4 字节单位），
 *   按 "底→顶" 顺序排 TOR 边界，只把用户区设为 U 可 RWX。
 ****************************************************************************/

static void configure_mpu(void)
{
  /* 1. [0, CONFIG_NUTTX_USERSPACE) : 内核+全集, U 不可访问（仅 M） */
  riscv_config_pmp_region(0, PMPCFG_A_TOR, CONFIG_NUTTX_USERSPACE, 0);

  /* 2. [USERSPACE, USERSPACE+SIZE) : 用户区, U 可 RWX */
  riscv_config_pmp_region(1, PMPCFG_A_TOR | PMPCFG_R | PMPCFG_W | PMPCFG_X,
                          CONFIG_NUTTX_USERSPACE + CONFIG_NUTTX_USERSPACE_SIZE,
                          0);

  /* 3. [USERSPACE+SIZE, 4GB) : 锁定兜底, U 不可访问 */
  riscv_config_pmp_region(2, PMPCFG_A_TOR | PMPCFG_L, UINT32_MAX, 0);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: k1r_userspace
 *
 * Description:
 *   清用户 .bss、拷贝用户 .data、配置 PMP。
 *   在内核启动、跳转到用户态（riscv_jump_to_user(nsh_main)）之前由
 *   __k1r_start/板级调用。
 ****************************************************************************/

void k1r_userspace(void)
{
  uint8_t *src;
  uint8_t *dest;
  uint8_t *end;

  /* 清用户 .bss */
  DEBUGASSERT(USERSPACE->us_bssstart != 0 && USERSPACE->us_bssend != 0 &&
              USERSPACE->us_bssstart <= USERSPACE->us_bssend);
  dest = (uint8_t *)USERSPACE->us_bssstart;
  end  = (uint8_t *)USERSPACE->us_bssend;
  while (dest != end)
    {
      *dest++ = 0;
    }

  /* 拷贝用户 .data（源 = 固件内 us_datasource 段） */
  DEBUGASSERT(USERSPACE->us_datasource != 0 &&
              USERSPACE->us_datastart != 0 && USERSPACE->us_dataend != 0 &&
              USERSPACE->us_datastart <= USERSPACE->us_dataend);
  src  = (uint8_t *)USERSPACE->us_datasource;
  dest = (uint8_t *)USERSPACE->us_datastart;
  end  = (uint8_t *)USERSPACE->us_dataend;
  while (dest != end)
    {
      *dest++ = *src++;
    }

  /* 配置 PMP 隔离内核/用户 */
  configure_mpu();
}

#endif /* CONFIG_BUILD_PROTECTED */

/****************************************************************************
 * vendor/SpaceMiT/chips/k1-rcpu/k1r_allocateheap.c
 *
 * SpacemiT K1 RCPU (Nuclei N308) 堆分配
 *
 * PROTECTED 下拆分内核/用户堆（参考 c906_allocateheap.c）：
 *   内核堆 : g_idle_topstack -> CONFIG_NUTTX_USERSPACE (M-only)
 *   用户堆 : USERSPACE->us_bssend -> us_heapend (用户区, U)
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/types.h>
#include <stdint.h>

#include <nuttx/arch.h>
#include <nuttx/board.h>
#include <nuttx/userspace.h>
#include <arch/board/board.h>

#include "riscv_internal.h"

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: up_allocate_heap
 *
 * Description:
 *   PROTECTED + MM_KERNEL_HEAP：返回用户堆（us_bssend -> us_heapend）。
 *   FLAT：返回整个堆（g_idle_topstack -> RAM_END）。
 ****************************************************************************/

void up_allocate_heap(void **heap_start, size_t *heap_size)
{
#if defined(CONFIG_BUILD_PROTECTED) && defined(CONFIG_MM_KERNEL_HEAP)
  uintptr_t ubase = (uintptr_t)USERSPACE->us_bssend;
  uintptr_t utop  = (uintptr_t)USERSPACE->us_heapend;
  size_t    usize = utop - ubase;

  board_autoled_on(LED_HEAPALLOCATE);

  *heap_start = (void *)ubase;
  *heap_size  = usize;

  /* PMP 已在 k1r_userspace() 里给用户区 U 权限 */
#else
  board_autoled_on(LED_HEAPALLOCATE);
  *heap_start = (void *)g_idle_topstack;
  *heap_size  = CONFIG_RAM_END - g_idle_topstack;
#endif /* CONFIG_BUILD_PROTECTED && CONFIG_MM_KERNEL_HEAP */
}

/****************************************************************************
 * Name: up_allocate_kheap
 *
 * Description:
 *   PROTECTED + MM_KERNEL_HEAP：返回内核堆（g_idle_topstack -> 用户区基址，M-only）。
 ****************************************************************************/

#if defined(CONFIG_BUILD_PROTECTED) && defined(CONFIG_MM_KERNEL_HEAP) && \
    defined(__KERNEL__)
void up_allocate_kheap(void **heap_start, size_t *heap_size)
{
  *heap_start = (void *)g_idle_topstack;
  *heap_size  = CONFIG_NUTTX_USERSPACE - g_idle_topstack;
}
#endif

